code_sketch:
// detour stage: active only while the control flag says so
interceptFrom("jms:queue:orders")
    .onWhen(exchangeProperty("detour.audit").isEqualTo(true))
    .to("bean:auditService?method=inspectAndTag");

from("jms:queue:orders")
    .to("bean:orderService");              // same destination on both legs

// out of band:
template.sendBody("controlbus:route?routeId=auditDetour&action=suspend", null);

