@Bean
IntegrationFlow auditDetour(AuditToggle toggle) {
    return IntegrationFlow.from("orders")
        .route(toggle::enabled,                       // flipped via the control bus
               m -> m.channelMapping(true, "ordersAudit")
                     .channelMapping(false, "orderService"))
        .get();
}
